def translations_for(question: dict) -> dict:
    out = {}
    for lang, (text, explanation) in TR[question["id"]].items():
        correct, wrong = ANSWERS.get(question["id"], {}).get(lang, (question["correctAnswer"], question["wrongAnswers"]))
        out[lang] = {"questionText": text, "correctAnswer": correct, "wrongAnswers": wrong, "explanation": explanation}
    return out
